// Kommun open data (folkmängd, elever per grade level, kommungrupp, peers).
// Generated by scripts/16-fetch-kommun-stats.js into data/kommun-stats/.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const DEFAULT_PATH = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../data/kommun-stats/kommun-stats.json',
);

// Folkmängd bands, the peer fallback when a kommun has no kommungrupp.
// `max` is exclusive; the last band has no upper bound.
export const SIZE_BANDS = Object.freeze([
  Object.freeze({ key: '<10k', min: 0, max: 10000 }),
  Object.freeze({ key: '10-25k', min: 10000, max: 25000 }),
  Object.freeze({ key: '25-50k', min: 25000, max: 50000 }),
  Object.freeze({ key: '50-100k', min: 50000, max: 100000 }),
  Object.freeze({ key: '>100k', min: 100000, max: null }),
]);

export function sizeBand(folkmangd) {
  if (!Number.isFinite(folkmangd)) return null;
  return SIZE_BANDS.find((b) => b.max == null || folkmangd < b.max).key;
}

const GRUNDSKOLA_BANDS = Object.freeze(['1-3', '4-6', '7-9']);

function maskedBandsOf(r) {
  const by = r.grundskola_masked_by_band;
  if (by && typeof by === 'object') return new Set(Object.keys(by).filter((k) => Number(by[k]) > 0));
  return Number(r.grundskola_masked_cells) > 0 ? new Set(GRUNDSKOLA_BANDS) : new Set();
}

class KommunStats {
  constructor(data) {
    this.data = data;
    this.records = new Map();
    for (const [kod, r] of Object.entries(data.kommuner ?? {})) {
      this.records.set(kod, {
        kod,
        namn: r.namn ?? null,
        lan: r.lan ?? null,
        folkmangd: r.folkmangd ?? null,
        sizeBand: sizeBand(r.folkmangd),
        kommungrupp: r.kommungrupp ?? null,
        peers: Array.isArray(r.peers) ? r.peers : [],
        elever: r.elever ?? {},
        // Skolverket masks grundskola cells under 5 pupils; a band with a
        // masked cell is a lower bound, not a count. Per band when the
        // snapshot says which; otherwise any masked cell marks all three.
        maskedBands: maskedBandsOf(r),
      });
    }
  }

  get(kod) {
    return this.records.get(kod) ?? null;
  }

  all() {
    return [...this.records.values()];
  }

  // Kommungrupp members, else same size band; never includes kod itself.
  peersOf(kod) {
    const me = this.get(kod);
    if (!me) return [];
    const same = me.kommungrupp
      ? (r) => r.kommungrupp === me.kommungrupp
      : (r) => me.sizeBand != null && r.sizeBand === me.sizeBand;
    return this.all().filter((r) => r.kod !== kod && same(r)).map((r) => r.kod);
  }

  // Sum of kommunal-regi elever over the requested grades. Introduktions-
  // programmet is part of Gymnasiet (counted once); Högskola is 0 elever.
  // null when the kommun is unknown or any needed grade is null/unknown or
  // has masked cells (the sum would be a lower bound, so a price per elev
  // divided by it would be too high).
  eleverIn(kod, grades) {
    const me = this.get(kod);
    if (!me) return null;
    const need = new Set();
    for (const g of grades) {
      if (g === 'Högskola') continue;
      need.add(g === 'Introduktionsprogrammet' ? 'Gymnasiet' : g);
    }
    let sum = 0;
    for (const g of need) {
      const v = me.elever[g];
      if (typeof v !== 'number' || !Number.isFinite(v) || me.maskedBands.has(g)) return null;
      sum += v;
    }
    return sum;
  }
}

let memo = null;
export function loadKommunStats({ path: p, data } = {}) {
  if (data) return new KommunStats(data);
  const file = p ?? DEFAULT_PATH;
  if (memo && memo.file === file) return memo.stats;
  const stats = new KommunStats(JSON.parse(readFileSync(file, 'utf8')));
  memo = { file, stats };
  return stats;
}
